462:         const dz = this.pos.z - c.z;
463:         const dist = Math.hypot(dx, dz);
464:         const min = c.r + r;
465:         if (dist < min && dist > 0.0001) {
466:           const push = (min - dist) / dist;
467:           this.pos.x += dx * push;
468:           this.pos.z += dz * push;
469:         }
470:         continue;
