    this.keys = new Set();
    this.firing = false;
    this.ads = false;
    this.interactHeld = false;
    this.dragging = false;
    this.locked = false;
    this.touch = { forward: 0, strafe: 0, fire: false, interact: false };

    this.ui.setWallet(this.wallet);
    this.bindInput();
    this.bindResize();

    this.spawnInitialDrones();
